    @Autowired protected com.library.catalogpublication.PublicationService publications;@Autowired protected CatalogSetService service;@Autowired protected JdbcTemplate jdbc;@Autowired protected IntakeCatalog intake;
    @Autowired protected com.fasterxml.jackson.databind.ObjectMapper applicationJson;@Autowired protected com.library.service.BookService books;@Autowired protected MockMvc mvc;@Autowired protected PlatformTransactionManager transactions;
    protected final CatalogSetSupport.Actor admin=new CatalogSetSupport.Actor(831001,true,false),clerk=new CatalogSetSupport.Actor(831002,false,true),other=new CatalogSetSupport.Actor(831003,true,false),reader=new CatalogSetSupport.Actor(831004,false,false);
    protected LinkedMultiValueMap<String,String> q(String... pairs){var q=new LinkedMultiValueMap<String,String>();for(int i=0;i<pairs.length;i+=2)q.add(pairs[i],pairs[i+1]);return q;}
    protected UsernamePasswordAuthenticationToken auth(CatalogSetSupport.Actor a){return new UsernamePasswordAuthenticationToken(a.id(),"synthetic",List.of(new SimpleGrantedAuthority(a.admin()?"ROLE_ADMIN":a.librarian()?"ROLE_LIBRARIAN":"ROLE_READER")));}
    @BeforeEach protected void cleanSources(){jdbc.update("DELETE FROM legacy_record WHERE display_name='合成B34来源'");}
    @BeforeEach protected void authenticate(){SecurityContextHolder.getContext().setAuthentication(auth(admin));}
    @AfterEach protected void clear(){SecurityContextHolder.clearContext();}
    protected long book(){return insert(jdbc,"INSERT INTO book(isbn,title,price,stock_total,stock_available) VALUES (?,?,12.34,0,0)","B34"+UUID.randomUUID().toString().replace("-","").substring(0,17),"合成套装书目📚"+UUID.randomUUID());}
    protected JsonNode context(long id){return service.bookContexts(q("bookId",""+id),admin).path("records").get(0);}
    protected JsonNode ev(){return obj("kind","MANUAL_REVIEW","reference","合成逐边独立核实依据📚");}
    protected JsonNode newMember(long id){JsonNode c=context(id);return obj("bookId",id,"expectedBook",obj("revision",c.path("book").get("revision"),"attributeRevision",c.path("book").get("attributeRevision"),"digest",c.get("bookDigest"),"sourceDigest",c.path("source").get("digest")),"evidence",ev());}
    protected ObjectNode input(String op){return obj("schemaVersion",1,"operationKey",UUID.randomUUID().toString(),"operation",op,"mode","MANUAL","reason","合成管理员明确维护依据");}
    protected ObjectNode create(JsonNode... rows){ObjectNode n=input("CREATE");n.put("clientRef","synthetic_set");n.put("name","合成套装📚"+UUID.randomUUID());n.set("note",NullNode.instance);n.set("evidence",ev());n.set("members",tree(Arrays.asList(rows)));return n;}
    protected JsonNode preview(JsonNode n){return service.preview(n,q(),admin);}
    protected JsonNode confirmation(JsonNode p){return obj("schemaVersion",1,"operationKey",p.get("operationKey"),"previewDigest",p.get("previewDigest"));}
    protected JsonNode confirm(JsonNode p){return service.confirm(p.path("requestId").asLong(),confirmation(p),q(),admin);}
    protected JsonNode cancel(JsonNode p,String reason){ObjectNode n=(ObjectNode)confirmation(p);n.put("reason",reason);return service.cancel(p.path("requestId").asLong(),n,q(),admin);}
    protected long set(){return confirm(preview(create())).path("result").path("set").path("setId").asLong();}
    protected ObjectNode operation(String op,long set){JsonNode s=service.getSet(set,q(),admin);ObjectNode n=input(op);n.put("setId",set);n.set("expectedSet",obj("revision",s.path("set").get("revision"),"digest",s.get("setDigest")));if(op.endsWith("_SET")||op.equals("UPDATE_METADATA"))n.set("evidence",ev());return n;}
    protected ObjectNode members(String op,long set,JsonNode... rows){ObjectNode n=operation(op,set);n.set("members",tree(Arrays.asList(rows)));return n;}
    protected JsonNode existing(long set,long book){JsonNode m=null;for(int page=1;;page++){JsonNode result=service.members(set,q("status","ALL","size","100","page",""+page),admin,true,false);for(JsonNode r:result.path("records"))if(r.path("member").path("bookId").asLong()==book)m=r;if(m!=null||page>=result.path("pages").asInt())break;}assertNotNull(m);ObjectNode n=(ObjectNode)newMember(book);n.set("membershipId",m.path("member").get("membershipId"));n.set("expectedMember",obj("revision",m.path("member").get("revision"),"digest",m.get("memberDigest")));return n;}
    protected void reason(String code,Runnable action){var e=assertThrows(CatalogSetSupport.Failure.class,action::run);assertEquals(code,e.code);}
    protected JsonNode http(org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder r,JsonNode body,CatalogSetSupport.Actor a,int status)throws Exception{if(body!=null)r.contentType("application/json").content(write(body));r.with(a==null?anonymous():authentication(auth(a)));var response=mvc.perform(r).andReturn().getResponse();assertEquals(status,response.getStatus(),response.getContentAsString());authenticate();return read(response.getContentAsString());}
    @Test void createGeneratedIdsFrozenPreviewAndSafeRead(){long b=book();JsonNode n=create(newMember(b)),p=preview(n);assertTrue(p.path("preview").path("after").path("set").get("setId").isNull());JsonNode r=confirm(p);long s=r.path("result").path("set").path("setId").asLong();assertTrue(s>0);assertTrue(r.path("result").path("set").get("clientRef").isNull());assertEquals("synthetic_set",r.path("result").path("createdSet").path("clientRef").asText());assertTrue(r.path("result").path("members").get(0).path("membershipId").asLong()>0);assertEquals(r,confirm(p));assertEquals(p.path("preview"),service.getRequest(p.path("requestId").asLong(),q(),admin).get("preview"));assertFalse(service.members(s,q(),clerk,false,false).toString().contains("evidence"));assertEquals(1,service.members(b,q(),clerk,false,true).path("total").asLong());}
    @Test void stableMemberIdsAndMultiSetAndSetLifecycle(){long b=book(),s=set(),t=set();JsonNode r=confirm(preview(members("ADD_MEMBERS",s,newMember(b))));long id=r.path("result").path("members").get(0).path("membershipId").asLong();confirm(preview(members("ADD_MEMBERS",t,newMember(b))));reason("MEMBERSHIP_EXISTS",()->preview(members("ADD_MEMBERS",s,newMember(b))));confirm(preview(members("RETIRE_MEMBERS",s,existing(s,b))));reason("MEMBERSHIP_EXISTS",()->preview(members("ADD_MEMBERS",s,newMember(b))));JsonNode restored=confirm(preview(members("RESTORE_MEMBERS",s,existing(s,b))));assertEquals(id,restored.path("result").path("members").get(0).path("membershipId").asLong());assertEquals(3,restored.path("result").path("members").get(0).path("revision").asLong());confirm(preview(operation("RETIRE_SET",s)));assertEquals(0,service.members(s,q(),clerk,false,false).path("records").get(0).path("effective").asBoolean()?1:0);reason("SET_RETIRED",()->preview(members("ADD_MEMBERS",s,newMember(book()))));confirm(preview(operation("RESTORE_SET",s)));assertTrue(service.members(s,q(),clerk,false,false).path("records").get(0).path("effective").asBoolean());assertEquals(2,service.members(b,q(),clerk,false,true).path("total").asLong());}
    @Test void noOpDoesNotChurnRevisionTimeEvidenceOrEvents(){long s=set();var before=jdbc.queryForMap("SELECT * FROM catalog_set WHERE id=?",s);long count=jdbc.queryForObject("SELECT COUNT(*) FROM catalog_set_event WHERE set_id=?",Long.class,s);JsonNode r=confirm(preview(operation("RESTORE_SET",s)));assertFalse(r.path("changed").asBoolean());assertTrue(r.path("eventIds").isEmpty());assertEquals(before,jdbc.queryForMap("SELECT * FROM catalog_set WHERE id=?",s));assertEquals(count,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_set_event WHERE set_id=?",Long.class,s));}
    @Test void cancellationIsPersistentIdempotentAndAllowsReediting(){long b=book();ObjectNode n=create(newMember(b));JsonNode p=preview(n),c=cancel(p,"EDIT");assertEquals("CANCELLED",c.path("state").asText());assertEquals(c,cancel(p,"EDIT"));reason("IDEMPOTENCY_KEY_REUSED",()->cancel(p,"ABANDON"));assertEquals(c,preview(n));reason("PREVIEW_CANCELLED",()->confirm(p));assertTrue(c.get("receipt").isNull());books.delete(b);assertEquals(1,jdbc.queryForObject("SELECT catalog_set_book_revision FROM book WHERE id=?",Long.class,b));JsonNode newPreview=preview(create());assertNotEquals(p.path("operationKey"),newPreview.path("operationKey"));}
    @Test void committedCancellationReturnsOriginalSuccessAndExpiryCannotAlterIt(){JsonNode p=preview(create()),r=confirm(p);assertEquals(r,cancel(p,"EDIT").get("receipt"));assertTrue(cancel(p,"EDIT").get("cancelledAt").isNull());assertEquals(r,confirm(p));}
    @Test void allRolesOwnershipAndRoleFirstMalformedInput()throws Exception{for(var a:new CatalogSetSupport.Actor[]{null,reader,clerk}){http(post("/catalog-sets/previews").contentType("application/json").content("bad"),null,a,403);http(get("/catalog-set-reviews?unknown=1"),null,a,403);}http(get("/catalog-sets/99999999"),null,reader,403);http(get("/catalog-sets/99999999"),null,null,403);JsonNode p=preview(create());reason("OWNER_REQUIRED",()->service.getRequest(p.path("requestId").asLong(),q(),other));reason("OWNER_REQUIRED",()->service.confirm(p.path("requestId").asLong(),confirmation(p),q(),other));var demoted=new CatalogSetSupport.Actor(admin.id(),false,true);reason("CATALOG_SET_ROLE_REQUIRED",()->service.getRequest(p.path("requestId").asLong(),q(),demoted));http(get("/catalog-sets?size=1"),null,clerk,200);}
    @Test void strictJsonUnknownDuplicateTrailingAndNumericShapes()throws Exception{ObjectNode n=create();http(post("/catalog-sets/previews"),n.deepCopy().put("extra",1),admin,400);http(post("/catalog-sets/previews").contentType("application/json").content(write(n).replace("\"mode\":\"MANUAL\"","\"mode\":\"MANUAL\",\"mode\":\"MANUAL\"")),null,admin,400);http(post("/catalog-sets/previews").contentType("application/json").content(write(n)+" {}"),null,admin,400);for(JsonNode v:List.of(tree("1"),tree(1.0),tree(9007199254740992L),tree(-1))){ObjectNode t=create();t.set("schemaVersion",v);reason("INVALID_INPUT",()->preview(t));}reason("INVALID_INPUT",()->preview(n.deepCopy().put("operationKey","00000000-0000-1000-a000-000000000000")));reason("INVALID_INPUT",()->preview(n.deepCopy().put("mode","SOURCE")));}
    @Test void unicodeCodePointsWhitespaceAndNullEmptyRemainExact(){for(String s:List.of("\u00a0","\u2007","\u202f","\u3000","\ud800","x\u0000","x\u007f"))reason("INVALID_INPUT",()->preview(create().put("name",s)));confirm(preview(create().put("name","📚".repeat(200)).put("note","\n\t\r<script>原文</script> union select")));reason("INVALID_INPUT",()->preview(create().put("name","📚".repeat(201))));long s=set();ObjectNode n=operation("UPDATE_METADATA",s);n.set("changes",obj("name",obj("action","KEEP"),"note",obj("action","SET","value","")));JsonNode r=confirm(preview(n));assertEquals("",r.path("result").path("set").path("note").asText());n=operation("UPDATE_METADATA",s);n.set("changes",obj("name",obj("action","KEEP"),"note",obj("action","CLEAR")));assertTrue(confirm(preview(n)).path("result").path("set").get("note").isNull());}
    @Test void strictQueriesAreNotCoercedAndPaginationIsReal()throws Exception{for(String query:List.of("size=101","page=0","page=1.0","size=1&size=2","unknown=1","status=active","page=9007199254740992"))http(get("/catalog-sets?"+query),null,admin,400);long s=set();JsonNode last=service.list(q("page","2147483647"),clerk);assertTrue(last.path("records").isEmpty());assertTrue(last.path("total").asLong()>0);reason("INVALID_INPUT",()->service.bookContexts(q("bookId","1","bookId","1"),admin));reason("INVALID_INPUT",()->service.bookContexts(q("bookId","1","page","1"),admin));}
    protected void metadata(long id,String f,Object v){var n=new com.library.dto.InventoryIntakeContracts.MetadataUpdate();n.setExpectedMetadataDigest(intake.view(id).metadataDigest());n.setChanges(obj(f,v));intake.update(id,n);}
    @Test void isbnAndTitleAbaAndB33RevisionGuardButPublicationIndependent(){long b=book();String isbn=intake.read(b).getIsbn();JsonNode p=preview(create(newMember(b)));metadata(b,"isbn","B34ABA"+b);metadata(b,"isbn",isbn);JsonNode original=p;reason("BOOK_IDENTITY_CHANGED",()->confirm(original));assertEquals(2,context(b).path("book").path("revision").asLong());p=preview(create(newMember(b)));metadata(b,"pages",0);metadata(b,"description","合成简介");metadata(b,"publishDate","2024-01-01");assertTrue(confirm(p).path("changed").asBoolean());long c=book();JsonNode b33=preview(create(newMember(c)));jdbc.update("INSERT INTO catalog_book_attribute(book_id,revision,display_title_override,display_origin,updated_at) VALUES (?,1,'合成展示','MANUAL',CURRENT_TIMESTAMP)",c);reason("BOOK_IDENTITY_CHANGED",()->confirm(b33));}
    @Test void previewsProtectDeleteAndHistoryRetainsProtection(){long b=book();JsonNode p=preview(create(newMember(b)));reason("CATALOG_SET_REFERENCED",()->books.delete(b));assertEquals(0,context(b).path("book").path("revision").asLong());long s=confirm(p).path("result").path("set").path("setId").asLong();confirm(preview(members("RETIRE_MEMBERS",s,existing(s,b))));confirm(preview(operation("RETIRE_SET",s)));reason("CATALOG_SET_REFERENCED",()->books.delete(b));}
    @Test void bounded100AtomicAndSortedCanonicalReplay(){List<JsonNode> rows=new ArrayList<>();for(int i=0;i<100;i++)rows.add(newMember(book()));Collections.reverse(rows);ObjectNode n=create(rows.toArray(JsonNode[]::new));JsonNode p=preview(n);Collections.reverse(rows);n.set("members",tree(rows));assertEquals(p,preview(n));assertEquals(100,confirm(p).path("result").path("members").size());rows.add(rows.get(0));reason("INVALID_INPUT",()->preview(create(rows.toArray(JsonNode[]::new))));reason("INVALID_INPUT",()->preview(create(rows.get(0),rows.get(0))));long s=set();reason("INVALID_INPUT",()->preview(members("ADD_MEMBERS",s)));}
    @Test void aggregateAndMemberAbaInvalidateOnlyAffectedSet(){long b=book(),s=set(),t=set();confirm(preview(members("ADD_MEMBERS",s,newMember(b))));JsonNode p=preview(operation("RETIRE_SET",s));confirm(preview(members("RETIRE_MEMBERS",s,existing(s,b))));confirm(preview(members("RESTORE_MEMBERS",s,existing(s,b))));JsonNode original=p;reason("CATALOG_SET_CHANGED",()->confirm(original));p=preview(operation("RETIRE_SET",s));confirm(preview(members("ADD_MEMBERS",t,newMember(b))));assertTrue(confirm(p).path("changed").asBoolean());}
    @Test void eventFailureAndReceiptFailureRollBackEverything(){for(boolean event:List.of(true,false)){JsonNode p=preview(create(newMember(book())));long request=p.path("requestId").asLong();String table=event?"catalog_set_event":"catalog_set_request",ck="ck_b34_fault_"+request;long sets=jdbc.queryForObject("SELECT COUNT(*) FROM catalog_set",Long.class);jdbc.execute("ALTER TABLE "+table+" ADD CONSTRAINT "+ck+" CHECK("+(event?"request_id<>"+request:"operation_key<>X'"+HexFormat.of().formatHex(bytes(p.path("operationKey").asText()))+"' OR state<>'COMMITTED'")+")");try{reason("CATALOG_SET_SAVE_FAILED",()->confirm(p));assertEquals(sets,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_set",Long.class));assertEquals("PREVIEWED",service.getRequest(request,q(),admin).path("state").asText());}finally{jdbc.execute("ALTER TABLE "+table+" DROP "+(service.sources.mysql?"CHECK ":"CONSTRAINT ")+ck);}confirm(p);}}
    @Test void originalKeyConcurrentPreviewAndConfirmOnlyOnce()throws Exception{ObjectNode n=create(newMember(book()));ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<JsonNode> x=pool.submit(()->preview(n)),y=pool.submit(()->preview(n));JsonNode p=x.get(20,TimeUnit.SECONDS);assertEquals(p,y.get(20,TimeUnit.SECONDS));Future<JsonNode> c=pool.submit(()->confirm(p)),d=pool.submit(()->confirm(p));assertEquals(c.get(20,TimeUnit.SECONDS),d.get(20,TimeUnit.SECONDS));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_set_event WHERE request_id=?",Long.class,p.path("requestId").asLong()));}finally{pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}
    @Test void legacyNormalizeSingleBatchAndFullPutAdvanceOnlyExactIdentity()throws Exception{long b=book();long category=insert(jdbc,"INSERT INTO book_category(name) VALUES (?)","合成B34完整表单分类");jdbc.update("UPDATE book SET category_id=? WHERE id=?",category,b);String isbn=intake.read(b).getIsbn();JsonNode p=preview(create(newMember(b)));http(put("/book-normalize/"+b),obj("isbn","B34N"+b),admin,200);http(put("/book-normalize/batch"),tree(List.of(obj("id",b,"isbn",isbn))),admin,200);reason("BOOK_IDENTITY_CHANGED",()->confirm(p));assertEquals(2,context(b).path("book").path("revision").asLong());JsonNode next=preview(create(newMember(b)));var dto=applicationJson.valueToTree(intake.read(b));String title=intake.read(b).getTitle();http(put("/books"),((ObjectNode)dto.deepCopy()).put("title","合成完整表单变化"),admin,200);http(put("/books"),dto,admin,200);assertEquals(4,context(b).path("book").path("revision").asLong());reason("BOOK_IDENTITY_CHANGED",()->confirm(next));assertFalse(dto.has("catalogSetBookRevision"));metadata(b,"title",title);assertEquals(4,context(b).path("book").path("revision").asLong());}
    @Test void expiryCancellationAndMaxRevisionsAreExact(){JsonNode p=preview(create(newMember(book())));jdbc.update("UPDATE catalog_set_request SET created_at='2000-01-01',expires_at='2000-01-02' WHERE id=?",p.path("requestId").asLong());reason("PREVIEW_EXPIRED",()->confirm(p));assertEquals("CANCELLED",cancel(p,"ABANDON").path("state").asText());long set=set();jdbc.update("UPDATE catalog_set SET revision=? WHERE id=?",CatalogSetSupport.MAX,set);assertFalse(confirm(preview(operation("RESTORE_SET",set))).path("changed").asBoolean());reason("REVISION_EXHAUSTED",()->preview(operation("RETIRE_SET",set)));long b=book();jdbc.update("UPDATE book SET catalog_set_book_revision=? WHERE id=?",CatalogSetSupport.MAX,b);metadata(b,"pages",0);reason("REVISION_EXHAUSTED",()->metadata(b,"isbn","B34MAX"+b));assertEquals(CatalogSetSupport.MAX,context(b).path("book").path("revision").asLong());}
    @Test void lastOf100DriftRollsBackAllAndUntouchedCountsUseEntireSet(){List<Long> ids=new ArrayList<>();List<JsonNode> rows=new ArrayList<>();for(int i=0;i<100;i++){long b=book();ids.add(b);rows.add(newMember(b));}long s=set();JsonNode p=preview(members("ADD_MEMBERS",s,rows.toArray(JsonNode[]::new)));metadata(ids.get(99),"title","合成最后一行变化");reason("BOOK_IDENTITY_CHANGED",()->confirm(p));assertEquals(0,service.members(s,q("status","ALL"),clerk,false,false).path("total").asLong());rows.clear();ids.forEach(id->rows.add(newMember(id)));confirm(preview(members("ADD_MEMBERS",s,rows.toArray(JsonNode[]::new))));long extra=book();JsonNode added=confirm(preview(members("ADD_MEMBERS",s,newMember(extra))));assertEquals(100,added.path("impact").path("unchangedActiveMembers").asLong());assertEquals(101,added.path("result").path("set").path("activeMemberCount").asLong());JsonNode retire=confirm(preview(members("RETIRE_MEMBERS",s,existing(s,extra))));assertEquals(100,retire.path("impact").path("unchangedActiveMembers").asLong());assertEquals(1,retire.path("result").path("set").path("retiredMemberCount").asLong());}
    @Test void sourceCrossBookAssociationDeletedAndFingerprintDrift(){long a=book(),b=book();String key=sourceCopy(b);source(a,key,"{\"套装类型\":\"套装中单本\"}");assertEquals(1,context(a).path("source").path("sourceCount").asLong());assertEquals(1,context(b).path("source").path("sourceCount").asLong());assertEquals("ASSOCIATION_INVALID",context(b).path("source").path("associationState").asText());JsonNode p=preview(create(newMember(a)));jdbc.update("UPDATE legacy_record SET details_json=? WHERE source_key=?","{\"套装类型\":\"暂无设置\"}",key);reason("SOURCE_CHANGED",()->confirm(p));jdbc.update("UPDATE book SET deleted=1 WHERE id=?",b);JsonNode list=service.reviews(q("scope","ALL","bookDeleted","ONLY","keyword",intake.read(a).getIsbn()),admin);assertEquals(0,list.path("total").asLong());JsonNode deleted=service.reviews(q("scope","ALL","bookDeleted","ONLY","keyword",jdbc.queryForObject("SELECT isbn FROM book WHERE id=?",String.class,b)),admin);assertTrue(deleted.path("records").toString().contains("SET_SOURCE_BOOK:"+b));}
    @Test void relationActionsKeepOldBookCopyAndFrozenRequestJsonByteExact(){long b=book();sourceCopy(b);var bookBefore=jdbc.queryForMap("SELECT * FROM book WHERE id=?",b);var copiesBefore=jdbc.queryForList("SELECT * FROM book_copy WHERE book_id=?",b);List<String> tables=List.of("inventory_intake_request","book_copy_action_request","catalog_attribute_request","catalog_identity_request","catalog_publication_request");Map<String,List<Map<String,Object>>> frozen=new TreeMap<>();for(String table:tables)frozen.put(table,jdbc.queryForList("SELECT request_json,preview_json,preview_digest,receipt_json FROM "+table+" ORDER BY id"));long s=confirm(preview(create(newMember(b)))).path("result").path("set").path("setId").asLong();confirm(preview(members("RETIRE_MEMBERS",s,existing(s,b))));confirm(preview(members("RESTORE_MEMBERS",s,existing(s,b))));confirm(preview(operation("RETIRE_SET",s)));confirm(preview(operation("RESTORE_SET",s)));assertEquals(bookBefore,jdbc.queryForMap("SELECT * FROM book WHERE id=?",b));assertEquals(CatalogSetUpgradeTest.fingerprint(copiesBefore),CatalogSetUpgradeTest.fingerprint(jdbc.queryForList("SELECT * FROM book_copy WHERE book_id=?",b)));for(String table:tables)assertEquals(frozen.get(table),jdbc.queryForList("SELECT request_json,preview_json,preview_digest,receipt_json FROM "+table+" ORDER BY id"),table);assertTrue(Arrays.stream(com.library.entity.Book.class.getDeclaredFields()).noneMatch(f->f.getName().equals("catalogSetBookRevision")));}
    @Test void firstPreviewStructuredRejectionsHaveNullRequestIdAndPersistNothing()throws Exception{long b=book();ObjectNode n=create(newMember(b));long count=jdbc.queryForObject("SELECT COUNT(*) FROM catalog_set_request",Long.class);metadata(b,"title","合成初次拒绝后重核对");JsonNode response=http(post("/catalog-sets/previews"),n,admin,409);assertEquals("BOOK_IDENTITY_CHANGED",response.path("data").path("reasonCode").asText());assertTrue(response.path("data").get("requestId").isNull());assertEquals(count,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_set_request",Long.class));reason("REQUEST_NOT_FOUND",()->service.byKey(q("key",n.path("operationKey").asText()),admin));ObjectNode invalid=create().put("name"," ");assertTrue(http(post("/catalog-sets/previews"),invalid,admin,400).path("data").get("requestId").isNull());assertEquals(count,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_set_request",Long.class));}
    @Test void changingReadClockKeepsOriginalPreviewAndEventDisplaySnapshot()throws Exception{long b=book();JsonNode p=preview(create(newMember(b))),frozen=p.path("preview").path("books").get(0);String at=frozen.path("source").path("readAt").asText();Thread.sleep(1100);JsonNode current=context(b);assertNotEquals(at,current.path("source").path("readAt").asText());assertEquals(frozen.path("source").path("digest"),current.path("source").path("digest"));long s=confirm(p).path("result").path("set").path("setId").asLong();assertEquals(p.path("preview"),service.getRequest(p.path("requestId").asLong(),q(),admin).path("preview"));assertEquals(at,service.events(s,q(),admin).path("records").get(0).path("books").get(0).path("source").path("readAt").asText());}
    @Test void realPublicationProtocolAllThreeFieldsLeavesB34PreviewValid(){long b=book();JsonNode p=preview(create(newMember(b)));var actor=new com.library.catalogpublication.PublicationSupport.Actor(admin.id(),true,false);JsonNode book=publications.book(b,actor).path("book");JsonNode n=obj("operationKey",UUID.randomUUID().toString(),"mode","MANUAL","reason","合成独立出版补录","entries",List.of(obj("bookId",b,"expectedRevision",book.get("revision"),"expectedMetadataDigest",book.get("metadataDigest"),"changes",obj("publishDate",obj("action","SET","value","2024-02-29"),"pages",obj("action","SET","value",0),"description",obj("action","SET","value","")),"evidence",ev())));JsonNode pub=publications.preview(n,actor);publications.confirm(pub.path("requestId").asLong(),obj("operationKey",pub.get("operationKey"),"previewDigest",pub.get("previewDigest")),actor);assertEquals(0,context(b).path("book").path("revision").asLong());assertTrue(confirm(p).path("changed").asBoolean());assertEquals(1,publications.book(b,actor).path("book").path("revision").asLong());}
    @Test void equivalentNonStringObjectOrderingDoesNotInventConflictInSqlFilters(){long b=book();source(b,sourceCopy(b),"{\"套装类型\":{\"longKey\":1,\"a\":false}}");source(b,sourceCopy(b),"{\"套装类型\":{\"a\":false,\"longKey\":1}}");assertEquals("WRONG_TYPE",context(b).path("source").path("markerState").asText());assertEquals(1,service.reviews(q("scope","ALL","keyword",intake.read(b).getIsbn(),"markerState","WRONG_TYPE"),admin).path("total").asLong());assertEquals(0,service.reviews(q("scope","ALL","keyword",intake.read(b).getIsbn(),"markerState","CONFLICT"),admin).path("total").asLong());}
    @Test void maintenancePageReusesBookIdentityAndKeepsDeletedHistoricalMembers(){long b=book();jdbc.update("INSERT INTO catalog_book_attribute(book_id,revision,display_title_override,display_origin,updated_at) VALUES (?,9,'合成维护展示名','MANUAL',CURRENT_TIMESTAMP)",b);JsonNode beforeContext=context(b);long set=confirm(preview(create(newMember(b)))).path("result").path("set").path("setId").asLong();JsonNode page=service.members(set,q("size","1"),admin,true,false),row=page.path("records").get(0);assertEquals(1,page.path("total").asLong());assertEquals(beforeContext.get("book"),row.path("book").get("book"));assertEquals(beforeContext.get("bookDigest"),row.path("book").get("bookDigest"));assertEquals(b,row.path("book").path("book").path("bookId").asLong());assertEquals(9,row.path("book").path("book").path("attributeRevision").asLong());confirm(preview(members("RETIRE_MEMBERS",set,existing(set,b))));jdbc.update("UPDATE book SET deleted=1 WHERE id=?",b);JsonNode history=service.members(set,q("status","RETIRED","size","20"),admin,true,false);assertEquals(1,history.path("total").asLong());assertEquals("RETIRED",history.path("records").get(0).path("member").path("status").asText());assertTrue(history.path("records").get(0).path("book").path("book").path("deleted").asBoolean());JsonNode emptyPage=service.members(set,q("status","ALL","page","999"),admin,true,false);assertEquals(1,emptyPage.path("total").asLong());assertTrue(emptyPage.path("records").isEmpty());long emptySet=set();assertEquals(0,service.members(emptySet,q(),admin,true,false).path("total").asLong());reason("SET_NOT_FOUND",()->service.members(CatalogSetSupport.MAX,q(),admin,true,false));}
