    protected long source(Long book,String key,String details){return insert(jdbc,"INSERT INTO legacy_record(source_system,record_type,source_key,book_id,details_json,display_name) VALUES ('huiben','BOOK',?,?,?,'合成B34来源')",key,book,details);}
